import{_ as l,a0 as a,w as p,s as o,ao as u,I as s,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"在 KDE 中添加、切换、删除和管理 Linux 用户 | LCTT x X-CMD","titleTemplate":false,"description":"在 KDE 中添加、切换、删除和管理 Linux 用户 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 KDE 中添加、切换、删除和管理 Linux 用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 KDE 中添加、切换、删除和管理 Linux 用户 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220218 Add, switch, delete, and manage Linux users in KDE","title":"在 KDE 中添加、切换、删除和管理 Linux 用户","tag":"202203","desc":""},"relativePath":"202203/20220218 Add, switch, delete, and manage Linux users in KDE.md","filePath":"[post].md"}'),d={name:"202203/20220218 Add, switch, delete, and manage Linux users in KDE.md"};function m(b,t,f,g,x,T){const r=a("Link");return p(),o("div",null,[t[25]||(t[25]=u('<h1 id="在-kde-中添加、切换、删除和管理-linux-用户" tabindex="-1">在 KDE 中添加、切换、删除和管理 Linux 用户 <a class="header-anchor" href="#在-kde-中添加、切换、删除和管理-linux-用户" aria-label="Permalink to “在 KDE 中添加、切换、删除和管理 Linux 用户”">​</a></h1><blockquote><p>在一台电脑上维护独立的用户是一种奢侈，也是保护你自己和你关心的人的数据安全的一个好方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/03/104151iwevek3xzcr1113u.jpg" alt=""></p><p>在一个家庭中共享一台电脑通常是一件很随意的事情。当你需要电脑时，你拿起它并开始使用它。这在理论上很简单，而且大部分情况下是有效的。也就是说，直到你不小心拿起公用电脑，不小心把你的服务器的正常运行时间的截图发到你伴侣的烹饪博客上。然后，就到了建立独立用户帐户的时候了。</p><p>从一开始，Linux 就是一个多用户系统。它的设计是把每个用户，只要他们登录，都当作一个独特的人，有一个属于他们自己的桌面，一个独特的网络浏览器配置文件，访问他们自己的文档和文件，等等。KDE Plasma 桌面做了很多工作，使得从一个帐户切换到另一个帐户很容易，但首先你必须为每个你期望使用电脑的人设置一个用户帐户。你也可以为客人设置一个特殊的帐户（我称这个帐户为 <code>guest</code>）。</p><h3 id="在-kde-中添加用户" tabindex="-1">在 KDE 中添加用户 <a class="header-anchor" href="#在-kde-中添加用户" aria-label="Permalink to “在 KDE 中添加用户”">​</a></h3>',6)),s("p",null,[t[1]||(t[1]=e("在 Linux 上有不同的方法来添加用户。一种方法是系统管理员式的 ",-1)),n(r,{href:"https://www.redhat.com/sysadmin/linux-commands-manage-users"},{default:i(()=>[...t[0]||(t[0]=[e("使用终端",-1)])]),_:1}),t[2]||(t[2]=e("。当你有很多用户需要添加时，这是非常有效的，所以你想把这个过程自动化或者只是减少鼠标点击的次数。",-1))]),t[26]||(t[26]=u('<p>不过在 Plasma 桌面上，你可以用<ruby>用户<rt>Users</rt></ruby>程序来添加用户。<ruby>用户<rt>Users</rt></ruby>实际上是<ruby>系统设置<rt>System Settings</rt></ruby>中的一个控制面板，但你可以从你的应用菜单中启动它，就像它是一个独立的应用。</p><p><img src="https://opensource.com/sites/default/files/kde-users.jpg" alt="Users in KDE System Settings" title="Users in KDE System Settings"></p><p>要添加一个用户，点击窗口底部的<ruby>添加新用户<rt>Add New User</rt></ruby>按钮。</p><p><img src="https://opensource.com/sites/default/files/kde-users-add.jpg" alt="Adding a user in KDE" title="Adding a user in KDE"></p><p>给新用户一个<ruby>名字<rt>Name</rt></ruby>和一个<ruby>用户名<rt>Username</rt></ruby>。这些可能是相同的，但意图是他们的名字是他们的姓名，而他们的用户名是他们用于使用的入口。例如，我的名字是 “Seth Kenlon”，而我的用户名是 <code>seth</code>。</p>',5)),s("p",null,[t[4]||(t[4]=e("将新用户指定为",-1)),t[5]||(t[5]=s("ruby",null,[e("标准用户"),s("rt",null,"Standard")],-1)),t[6]||(t[6]=e("或",-1)),t[7]||(t[7]=s("ruby",null,[e("管理员"),s("rt",null,"Administraor")],-1)),t[8]||(t[8]=e("。标准用户只对自己的环境有完全的控制权。他们可以 ",-1)),n(r,{href:"https://opensource.com/article/21/11/install-flatpak-linux"},{default:i(()=>[...t[3]||(t[3]=[e("安装 Flatpak",-1)])]),_:1}),t[9]||(t[9]=e(" 并将数据保存到他们的主目录，但他们不能影响机器上的其他用户。这是有用户帐户的好处之一。我不会认为我允许使用我的电脑的任何人打算删除对我很重要的数据，但意外还是发生了。通过为我自己和我的伴侣创建一个单独的用户帐户，我在保护我们每个人的数据，我也在保护我们每个人，避免意外地移动一个文件或误放对另一个人很重要的数据。",-1))]),t[27]||(t[27]=u('<p>管理员可以进行全系统的更改。我通常在我的电脑上为自己保留这个角色，我也希望我的伴侣在她自己的电脑上为自己保留这个角色。然而，在工作中，这个角色属于 IT 部门。</p><p>为用户创建一个<ruby>密码<rt>Password</rt></ruby>，并重复<ruby>确认<rt>Confirm</rt></ruby>。登录后，新用户可以改变他们的密码。</p><p>要完成用户创建，请点击<ruby>创建<rt>Create</rt></ruby>按钮。</p><h3 id="切换用户" tabindex="-1">切换用户 <a class="header-anchor" href="#切换用户" aria-label="Permalink to “切换用户”">​</a></h3><p>在桌面有两种不同的方式来切换用户。你可以注销，然后让另一个用户登录，或者你可以从应用菜单的<ruby>电源/会话<rt>Power / Sessions</rt></ruby>子菜单中选择<ruby>切换用户<rt>Switch user</rt></ruby>。</p><p><img src="https://opensource.com/sites/default/files/kde-users-switch.jpg" alt="Switching users in KDE" title="Switching users in KDE"></p><p>当一个新用户登录时，你的当前桌面会被“冻结”或暂停，而另一个用户的新桌面会被调出来。你所有的窗口都保持打开。你甚至可以在游戏中切换用户（如果你正在战斗中，你应该先暂停一下），当你切换回来时，你可以从你离开的地方继续。更好的是，你的所有进程也会继续运行。所以你可以在渲染视频或编译代码时切换用户，当你切换回来时，你的视频已经完成了渲染，或者你的代码已经完成了编译（只要有足够的时间）。</p><p><img src="https://opensource.com/sites/default/files/kde-users-login.jpg" alt="Login" title="Login"></p><h3 id="删除用户" tabindex="-1">删除用户 <a class="header-anchor" href="#删除用户" aria-label="Permalink to “删除用户”">​</a></h3><p>当我有客人时，我经常在他们的逗留期间创建一个客人帐户，当他们离开后，我就删除这个帐户。</p><p>你可以通过删除一个用户的用户帐户来从你的电脑中删除该用户。这将删除他们的所有数据，所以要确保你要删除的用户已经把他们需要的东西从机器上迁移掉了！</p><p><ruby>删除用户<rt>Delete User</rt></ruby>按钮位于<ruby>用户<rt>Users</rt></ruby>控制面板中的每个用户帐户下，也就是你最初创建用户的地方。</p><p><img src="https://opensource.com/sites/default/files/kde-users-delete.jpg" alt="Deleting a user" title="Deleting a user"></p><h3 id="linux-用户管理" tabindex="-1">Linux 用户管理 <a class="header-anchor" href="#linux-用户管理" aria-label="Permalink to “Linux 用户管理”">​</a></h3><p>在计算机上维护独立的用户是一种奢侈，也是保护你自己的数据和你关心的人的数据安全的好方法。它允许每个用户都是独一无二的，并使桌面成为他们自己的。在 Linux 中，这很容易，而且没什么影响，因此可以为朋友、房客和家人创建用户。</p><hr>',16)),s("p",null,[t[11]||(t[11]=e("via: ",-1)),n(r,{href:"https://opensource.com/article/22/2/manage-linux-users-kde"},{default:i(()=>[...t[10]||(t[10]=[e("https://opensource.com/article/22/2/manage-linux-users-kde",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=e("作者：",-1)),n(r,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[12]||(t[12]=[e("Seth Kenlon",-1)])]),_:1}),t[17]||(t[17]=e(" 选题：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[13]||(t[13]=[e("lujun9972",-1)])]),_:1}),t[18]||(t[18]=e(" 译者：",-1)),n(r,{href:"https://github.com/geekpi"},{default:i(()=>[...t[14]||(t[14]=[e("geekpi",-1)])]),_:1}),t[19]||(t[19]=e(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:i(()=>[...t[15]||(t[15]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=e("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[20]||(t[20]=[e("LCTT",-1)])]),_:1}),t[23]||(t[23]=e(" 原创编译，",-1)),n(r,{href:"https://linux.cn/"},{default:i(()=>[...t[21]||(t[21]=[e("Linux中国",-1)])]),_:1}),t[24]||(t[24]=e(" 荣誉推出",-1))])])}const k=l(d,[["render",m]]);export{L as __pageData,k as default};
